                var before = h[5] ? h[5].price : 12.99, after = h[ds.matched - 1] ? h[ds.matched - 1].price : before;
                found.push({ m: ds.matched, tp: self._t('tp_match', { m: ds.matched, a: self._usd(before, 2), b: self._usd(after, 2) }),
                    ins: self._t('ins_match', { a: self._usd(h[ds.matched - 2] ? h[ds.matched - 2].arpu : before, 2), b: self._usd(last.arpu, 2) }) });
            }
            var paidMonths = cnt(function (r) { return r.channel === 'paid'; });
            if (paidMonths >= 6 && !(last.ratio >= 3 && last.runway >= 12)) {
                var fp = firstWhere(function (r) { return r.channel === 'paid'; });
                found.push({ m: fp.m, tp: self._t('tp_paid', { m: fp.m, n: paidMonths, r: self._x(last.ratio), c: self._pct(last.churn) }),
                    ins: self._t('ins_paid', { s: self._num(paidShare, 0), c: self._usd(last.cac), l: self._usd(last.ltv) }) });
            }
            var premiumOnly = cnt(function (r) { return r.price >= 17.99; }) >= 8 && cnt(function (r) { return r.channel === 'organic'; }) >= 8;
            if (premiumOnly && last.ratio >= 3 && last.mrr < 60000) {
                found.push({ m: 1, tp: self._t('tp_premium', { r: self._x(last.ratio), mrr: self._usd(last.mrr) }), ins: self._t('ins_premium', { mrr: self._usd(last.mrr) }) });
            }
            var early = firstWhere(function (r) { return r.notes && r.notes.indexOf('earlyB2B') >= 0; });
            if (early) {
                found.push({ m: early.m, tp: self._t('tp_earlyb2b', { m: early.m }), ins: self._t('ins_earlyb2b', { n: ds.flags.earlyB2B }) });
            }
            var flop = firstWhere(function (r) { return r.notes && r.notes.indexOf('flop') >= 0; });
            if (flop) { found.push({ m: flop.m, tp: self._t('tp_flop', { m: flop.m, s: self._num(flop.subs) }), ins: self._t('ins_flop', { m: flop.m }) }); }
            if (ds.buggy) { found.push({ m: ds.launchMonth, tp: self._t('tp_buggy', { m: ds.launchMonth }), ins: self._t('ins_buggy', { m: ds.launchMonth }) }); }
            if (!ds.launchMonth || ds.launchMonth > 10) {
                var lateTxt = ds.launchMonth ? self._t('ins_late', { m: ds.launchMonth }) : self._t('ins_nolaunch');
                found.push({ m: ds.launchMonth || 11, tp: ds.launchMonth ? self._t('tp_late', { m: ds.launchMonth }) : self._t('tp_nolaunch'), ins: lateTxt, soft: !ds.launchMonth });
            }

            found.sort(function (a, b) { return (a.soft ? 1 : 0) - (b.soft ? 1 : 0) || a.m - b.m; });
            var turning = '';
            if (found.length) { turning = found[0].tp; }
            else {
                var sh = ds.scoreHistory || [], worst = 0, wm = 0;
                for (var i = 1; i < sh.length; i++) { if (sh[i] - sh[i - 1] < worst) { worst = sh[i] - sh[i - 1]; wm = i + 1; } }
                turning = wm ? self._t('tp_none', { m: wm, a: sh[wm - 2], b: sh[wm - 1], c: sh[sh.length - 1] }) : self._t('tp_none_flat', { c: sh[sh.length - 1] });
            }

            var ins = [];
            for (var f = 0; f < found.length && ins.length < 3; f++) { ins.push(found[f].ins); }
            var retMonths = cnt(function (r) { return r.focus === 'retention'; });
            if (ins.length < 5) { ins.push(self._t('ins_churn', { a: self._pct(first.churn), b: self._pct(last.churn), n: retMonths })); }
            if (ins.length < 5) {
                ins.push(last.contracts > 0 ? self._t('ins_b2b', { n: last.contracts, s: self._num(last.mrr ? 100 * last.b2bMrr / last.mrr : 0, 0) }) : self._t('ins_nob2b'));
            }
            if (ins.length < 5 && ds.launchMonth && ds.launchMonth <= 10 && !ds.buggy) { ins.push(self._t('ins_wear', { m: ds.launchMonth, s: self._num(100 * last.wearShare, 0) })); }
            if (ins.length < 5 && !ds.matched && h.length >= 9 && h[8].price >= (h[5] ? h[5].price : 0) * 0.92) {
                var peak = 0, pm = 7; for (var k = 6; k < Math.min(9, h.length); k++) { if (h[k].churn > peak) { peak = h[k].churn; pm = h[k].m; } }
                ins.push(self._t('ins_held', { p: self._usd(h[8].price, 2), c: self._pct(peak), m: pm }));
            }
            if (ins.length < 5) { ins.push(self._t('ins_money', { cash: self._usd(last.cash), r: self._runway(last.runway, true), rev: self._usd(ds.revenueTotal || 0) })); }

            var q = [];
            q.push(found.length ? self._t('q_turn', { m: found[0].m }) : self._t('q_hold'));
            var gr = last.ratio >= 3, gw = last.runway >= 12;
            q.push(gr && gw ? self._t('q_gate_ok', { r: self._x(last.ratio) }) : self._t('q_gate_no', { leg: !gr && !gw ? self._t('leg_both') : (!gr ? self._t('leg_ratio') : self._t('leg_runway')) }));
            q.push(self._t('q_case'));
            return { turning: turning, insights: ins.slice(0, 5), questions: q, found: found };
        }

        _debriefHTML(ds, summary) {
            var self = this, h = ds.hist || [];
            if (!h.length) { return ''; }
            var last = h[h.length - 1], perf = ds.performance || {}, s = perf.overallScore || 0, tier = perf.tier || SBModel.tier(s, perf.cap);
            var a = this._analyse(ds);
            var gr = last.ratio >= 3, gw = last.runway >= 12;
            var gateCls = gr && gw ? 'is-ok' : 'is-no';
            var gateTxt = gr && gw ? this._t('d_gate_ok', { r: this._x(last.ratio), w: this._runway(last.runway, true) })
                : this._t('d_gate_no', { r: this._x(last.ratio), w: this._runway(last.runway, true) });
            var k = function (label, val) { return '<div class="sb-dkpi"><span>' + label + '</span><strong>' + val + '</strong></div>'; };
            var html = '<div class="sb-debrief-head">'
                + '<p class="sb-kicker">' + this._t('d_kicker') + '</p>'
                + '<h2 class="sb-h2" id="sbDebriefTitle">' + this._t('d_title') + '</h2>'
                + '<p class="sb-debrief-score"><strong>' + s + '</strong><small>/100</small><span class="sb-chip sb-chip-' + tier + '">' + this._t('perf_' + tier) + '</span></p>'
                + '<p class="sb-debrief-sub">' + this._t('d_sub', { o: perf.outcome, p: perf.process }) + '</p></div>'
                + '<div class="sb-dkpis">'
                + k(this._t('d_k_mrr'), this._usd(last.mrr)) + k(this._t('d_k_subs'), this._num(last.subs))
                + k(this._t('d_k_ratio'), this._x(last.ratio)) + k(this._t('d_k_runway'), this._runway(last.runway))
                + k(this._t('d_k_cash'), this._usd(last.cash)) + k(this._t('d_k_rev'), this._usd(ds.revenueTotal || 0))
                + k(this._t('d_k_b2b'), this._num(last.contracts)) + '</div>'
                + '<p class="sb-gate-line ' + gateCls + '">' + gateTxt + '</p>'
                + (perf.cap === 'gate' ? '<p class="sb-notice">' + this._t('cap_gate') + '</p>' : '')
                + (perf.cap === 'cash' ? '<p class="sb-notice">' + this._t('cap_cash') + '</p>' : '')
                + '<h3>' + this._t('d_turning') + '</h3><p class="sb-turning">' + a.turning + '</p>'
                + '<h3>' + this._t('d_insights') + '</h3><ul class="sb-insights">' + a.insights.map(function (x) { return '<li>' + x + '</li>'; }).join('') + '</ul>'
                + '<h3>' + this._t('d_questions') + '</h3><ol class="sb-questions">' + a.questions.map(function (x) { return '<li>' + x + '</li>'; }).join('') + '</ol>';
            return html;
        }

        /* ---------- painting ---------- */
        _runOver(st) {
            try { if (window.mySimulation && typeof window.mySimulation.isRunComplete === 'function') { return !!window.mySimulation.isRunComplete(); } } catch (e) {}
            var maxP = (st && st.maxPeriods) || 12;
            if (st && st.currentPeriod > maxP) { return true; }
            var h = (st && st.history) || (window.mySimulation && window.mySimulation.history) || [];
            return h.length >= maxP;
        }

        _bind() {
            if (this._bound) { return; }
            this._bound = true;
            var self = this;
            SB_IDS.forEach(function (id) {
                var el = document.getElementById(id);
                if (!el) { return; }
                var h = function () { try { self._paintOutputs(); self._paintPreview(); var v = self._el('sbValidation'); if (v) { v.textContent = ''; } } catch (e) {} };
                el.addEventListener('input', h);
                el.addEventListener('change', h);
            });
            document.addEventListener('express:langchanged', function () { try { self._render(); self._paintCharts(); } catch (e) {} });
            var f = window.mySimulation;
            if (f && f.eventBus && typeof f.eventBus.on === 'function') {
                f.eventBus.on('language:changed', function () { try { self._render(); self._paintCharts(); } catch (e) {} });
                f.eventBus.on('period:submitted', function () { try { self._render(); } catch (e) {} });
                f.eventBus.on('period:undone', function () { try { self._render(); } catch (e) {} });
                f.eventBus.on('state:loaded', function () { try { self._render(); } catch (e) {} });
                f.eventBus.on('simulation:complete', function () { try { self._render(); } catch (e) {} });
            }
        }

        _render() {
            var st = this._state();
            if (!st || !st.domainState) { return; }
            var ds = st.domainState;
            var over = this._runOver(st);
            var m = over ? (st.history ? st.history.length : 12) : (st.currentPeriod || 1);
            this._paintStatic();
            this._paintSteps(m, over);
            this._paintBriefing(m, over);
            this._paintKpis(ds);
            this._paintScore(ds);
            this._paintResult(ds);
            this._paintOutputs();
            this._paintPreview();
            this._paintChartAlt(ds);
            var form = this._el('sbForm'), deb = this._el('debriefPanel');
            if (over) {
                if (form) { form.hidden = true; }
                if (deb) { deb.innerHTML = this._debriefHTML(ds, this.getPerformanceSummary(st.history)); deb.hidden = false; }
            } else {
                if (form) { form.hidden = false; }
                if (deb) { deb.hidden = true; deb.innerHTML = ''; }
            }
            try { document.documentElement.lang = this._lang(); } catch (e) {}
        }

        _paintStatic() {
            var terms = ['mrr', 'cac', 'ltv', 'ratio', 'churn', 'runway', 'arpu', 'value', 'b2b', 'wear'];
            var html = '';
            for (var i = 0; i < terms.length; i++) { html += '<dt>' + this._t('g_' + terms[i]) + '</dt><dd>' + this._t('g_' + terms[i] + '_d') + '</dd>'; }
            this._set('sbGlossary', html);
            this._set('budgetMin', this._usd(5000));
            this._set('budgetMid', this._usd(27500));
            this._set('budgetMax', this._usd(50000));
            this._set('priceMin', this._usd(4.99, 2));
            this._set('priceMid', this._usd(17.49, 2));
            this._set('priceMax', this._usd(29.99, 2));
        }

        _paintSteps(m, over) {
            var html = '';
            for (var i = 1; i <= 12; i++) {
                var cls = (i < m || (over && i <= m)) ? 'is-done' : (i === m ? 'is-now' : '');
                if ([4, 7, 10, 12].indexOf(i) >= 0) { cls += ' is-key'; }
                html += '<li class="' + cls + '"><span>' + i + '</span></li>';
            }
            this._set('sbSteps', html);
            var c = this._el('sbCal');
            if (c) { c.textContent = over ? this._t('run_complete') : this._cal(m); }
        }

        _paintBriefing(m, over) {
            var st = this._state(), ds = st && st.domainState;
            this._set('sbEventTag', over ? this._t('tag_done') : this._t('tag_' + m));
            this._set('sbBriefTitle', over ? this._t('brief_done_title') : this._t('brief_title_' + m));
            var txt = over ? this._t('brief_done') : this._t('brief_' + m, { cut: ds ? ds.cutDepth : 10 });
            if (!over && ds && ds.priceWar && m >= ds.priceWar) { txt += ' ' + this._t('brief_war'); }
            this._set('briefingText', txt);
            this._set('sbBoardNote', over ? '' : this._t('board_note'));
            var tag = this._el('sbEventTag');
            if (tag) { tag.className = 'sb-tag' + (!over && SB_ALERT.indexOf(m) >= 0 ? ' is-alert' : ''); }
        }

        _delta(cur, prev, fmt) {
            if (prev == null) { return ''; }
            var d = cur - prev, cls = d > 0 ? 'is-up' : (d < 0 ? 'is-down' : 'is-flat');
            return '<span class="sb-delta ' + cls + '">' + (d > 0 ? '▲ +' : d < 0 ? '▼ ' : '') + fmt(d) + '</span> ' + this._t('vs_prev');
        }

        _paintKpis(ds) {
            var self = this, h = ds.hist || [], last = h[h.length - 1], prev = h[h.length - 2];
            if (!last) {
                this._set('cashDisplay', this._usd(ds.cash));
                this._set('cashSub', this._t('cash_start'));
                this._set('subsDisplay', '0');
                this._set('subsSub', this._t('subs_start'));
                this._set('mrrDisplay', this._usd(0));
                this._set('mrrSub', this._t('mrr_start'));
                this._set('ratioDisplay', '—');
                this._set('ratioSub', this._t('ratio_start'));
                return;
            }
            this._set('cashDisplay', this._usd(last.cash));
            var cd = this._el('cashDisplay'); if (cd) { cd.className = 'sb-kpi-value' + (last.cash <= 0 ? ' is-bad' : ''); }
            this._set('cashSub', last.net >= 0 ? this._t('runway_positive') : this._runway(last.runway) + ' · ' + this._t('burn_label', { v: this._usd(-last.net) }));
            this._set('subsDisplay', this._num(last.subs));
            this._set('subsSub', this._delta(last.subs, prev ? prev.subs : null, function (d) { return self._num(Math.abs(d)); }) + (prev ? ' · ' : '') + this._t('users_all', { n: this._num(last.users) }));
            this._set('mrrDisplay', this._usd(last.mrr));
            this._set('mrrSub', this._t('mrr_split', { c: this._usd(last.consumerMrr), b: this._usd(last.b2bMrr) }));
            this._set('ratioDisplay', this._x(last.ratio));
            var rd = this._el('ratioDisplay'); if (rd) { rd.className = 'sb-kpi-value' + (last.ratio < 3 ? ' is-bad' : ''); }
            this._set('ratioSub', this._t('ratio_sub', { l: this._usd(last.ltv), c: this._usd(last.cac) }));
        }

        _paintScore(ds) {
            var h = ds.hist || [], last = h[h.length - 1], p = ds.performance || {};
            if (!last) {
                this._set('sbScoreCard', '<p class="sb-score-head">' + this._t('score_title') + '</p><p class="sb-score-empty">' + this._t('score_empty') + '</p>');
                return;
            }
            var tier = p.tier || 'atrisk';
            var bar = function (label, v, cls) {
                var pct = Math.round(100 * (v || 0));
                return '<div class="sb-bar"><span>' + label + '</span><span class="sb-bar-track"><span class="sb-bar-fill ' + cls + '" style="width:' + pct + '%"></span></span><span class="sb-bar-val">' + pct + '</span></div>';
            };
            var gr = last.ratio >= 3, gw = last.runway >= 12;
            var html = '<p class="sb-score-head">' + this._t('score_title')
                + '<span class="sb-score-num">' + p.overallScore + '<small>/100</small></span>'
                + '<span class="sb-chip sb-chip-' + tier + '">' + this._t('perf_' + tier) + '</span></p>'
                + bar(this._t('bar_unit'), p.unitEconomics, 'is-outcome') + bar(this._t('bar_runway'), p.runway, 'is-runway')
                + bar(this._t('bar_scale'), p.scale, 'is-scale') + bar(this._t('bar_process'), (p.process || 0) / 100, 'is-process')
                + '<p class="sb-gate"><span class="' + (gr ? 'is-ok' : 'is-no') + '">' + (gr ? '✓ ' : '✗ ') + this._t('gate_ratio') + '</span>'
                + '<span class="' + (gw ? 'is-ok' : 'is-no') + '">' + (gw ? '✓ ' : '✗ ') + this._t('gate_runway') + '</span></p>'
                + '<p class="sb-score-note">' + this._t('score_note') + '</p>'
                + (p.cap === 'cash' ? '<p class="sb-score-cap">' + this._t('cap_cash') + '</p>' : '');
            this._set('sbScoreCard', html);
        }

        _paintResult(ds) {
            var h = ds.hist || [], r = h[h.length - 1], prev = h[h.length - 2];
            if (!r) {
                this._set('sbResultPanel', '<h3 class="sb-h3">' + this._t('res_title_0') + '</h3><p class="sb-result-head">' + this._t('res_empty') + '</p>');
                return;
            }
            var li = [];
            li.push(this._t('res_rev', { mrr: this._usd(r.mrr), d: prev ? (r.mrr - prev.mrr >= 0 ? '+' : '−') + this._usd(Math.abs(r.mrr - prev.mrr)) : this._usd(r.mrr), s: this._num(r.subs), a: this._usd(r.arpu, 2), b: this._usd(r.b2bMrr), e: r.contracts }));
            li.push(this._t('res_acq', { n: this._num(r.newPaid), p: this._num(r.newPaidPaid), c: this._num(r.newPaidContent), w: this._num(r.newPaidWom), cac: this._usd(r.cac) }));
            var why = [];
            if (r.paidMix >= 0.5) { why.push(this._t('why_paid')); }
            if (r.retStock >= 1) { why.push(this._t('why_ret')); }
            if (r.wearShare > 0) { why.push(this._t('why_wear', { s: this._num(100 * r.wearShare, 0) })); }
            if (r.shock >= 1) { why.push(this._t('why_shock', { p: this._num(r.dPrice, 0) })); }
            if (r.cut) { why.push(this._t('why_cut')); }
            if (r.m === 8) { why.push(this._t('why_slow')); }
            li.push(this._t('res_churn', { c: this._pct(r.churn), n: this._num(r.churned), why: why.length ? ' (' + why.join(', ') + ')' : '' }));
            li.push(this._t('res_cash', { net: (r.net >= 0 ? '+' : '−') + this._usd(Math.abs(r.net)), cash: this._usd(r.cash), w: this._runway(r.runway) }));
            var notes = r.notes || [];
            for (var i = 0; i < notes.length; i++) { li.push('<strong>' + this._t('note_' + notes[i], { m: r.m, mm: r.m + 2 }) + '</strong>'); }
            if (r.closed > 0) { li.push('<strong>' + this._t('note_closed', { n: r.closed, e: r.contracts }) + '</strong>'); }
            this._set('sbResultPanel', '<h3 class="sb-h3">' + this._t('res_title', { m: r.m }) + '</h3><ul class="sb-why">' + li.map(function (x) { return '<li>' + x + '</li>'; }).join('') + '</ul>');
        }

        _paintOutputs() {
            var b = this._el('marketingBudgetInput'), p = this._el('monthlyPriceInput');
            if (b) { this._set('budgetOut', this._usd(parseFloat(b.value) || 0)); }
            if (p) { this._set('priceOut', this._usd(parseFloat(p.value) || 0, 2)); }
        }

        _paintPreview() {
            var st = this._state();
            if (!st || !st.domainState) { return; }
            var ds = st.domainState, m = st.currentPeriod || 1;
            var b = parseFloat((this._el('marketingBudgetInput') || {}).value) || 0;
            var p = parseFloat((this._el('monthlyPriceInput') || {}).value) || 0;
            var ch = (this._el('channelStrategySelect') || {}).value || '';
            var fixed = SBModel.M.FIXED + (m >= 4 ? SBModel.M.COMPLIANCE : 0);
            var cost = fixed + b;
            var prevPrice = ds.hist && ds.hist.length ? ds.price : 12.99;
            var dp = prevPrice ? 100 * (p - prevPrice) / prevPrice : 0;
            var conv = ch === 'b2b' ? Math.round(b * 0.5 / SBModel.M.B2B_CONV_COST) : 0;
            var item = function (label, val, warn) { return '<div class="sb-prev-item' + (warn ? ' is-warn' : '') + '"><span>' + label + '</span><strong>' + val + '</strong></div>'; };
            var html = item(this._t('prev_costs'), this._usd(cost))
                + item(this._t('prev_cash'), this._usd(ds.cash - cost), ds.cash - cost < 0)
                + item(this._t('prev_price'), (dp > 0.05 ? '+' : '') + this._pct(dp, 0))
                + item(this._t('prev_b2b'), conv ? this._t('prev_b2b_v', { n: conv, m: m + 2 }) : this._t('prev_none'));
            this._set('sbPreview', html);
        }

        _paintChartAlt(ds) {
            var h = ds.hist || [];
            if (!h.length) { this._set('mrrChartAlt', this._t('alt_empty')); this._set('usersChartAlt', this._t('alt_empty')); return; }
            var l = h[h.length - 1], f = h[0];
            this._set('mrrChartAlt', this._t('alt_mrr', { a: this._usd(f.mrr), b: this._usd(l.mrr), c: this._usd(l.consumerMrr), d: this._usd(l.b2bMrr), n: this._usd(l.net) }));
            this._set('usersChartAlt', this._t('alt_users', { a: this._num(f.subs), b: this._num(l.subs), c: this._pct(f.churn), d: this._pct(l.churn) }));
        }

        _paintCharts() {
            try {
                var f = window.mySimulation;
                if (f && f.uiManager && typeof f.uiManager.updateCharts === 'function') { f.uiManager.updateCharts(f.state); }
            } catch (e) {}
        }

